create table if not exists fiscal_invoices (id bigserial primary key,access_key char(44) not null unique,model varchar(10),series varchar(10),invoice_number varchar(30) not null,issued_at timestamp not null,supplier_id bigint references suppliers_3d(id),issuer_name varchar(180) not null,issuer_document varchar(20) not null,total_products numeric(14,2) not null default 0,total_freight numeric(14,2) not null default 0,total_discount numeric(14,2) not null default 0,total_taxes numeric(14,2) not null default 0,total_invoice numeric(14,2) not null default 0,xml_storage_name varchar(255) not null unique,imported_by bigint not null references admin_users(id),created_at timestamp default current_timestamp);
create index if not exists fiscal_invoices_issued_idx on fiscal_invoices(issued_at);
create index if not exists fiscal_invoices_issuer_idx on fiscal_invoices(issuer_document);
create table if not exists fiscal_invoice_items (id bigserial primary key,fiscal_invoice_id bigint not null references fiscal_invoices(id) on delete cascade,item_number integer not null,supplier_product_code varchar(80),ean varchar(30),description varchar(255) not null,ncm varchar(20),cfop varchar(10),unit varchar(10),quantity numeric(14,4) not null default 0,unit_price numeric(14,6) not null default 0,total_price numeric(14,2) not null default 0,is_filament boolean not null default false,filament_id bigint references filaments_3d(id),created_at timestamp default current_timestamp,unique(fiscal_invoice_id,item_number));
alter table filaments_3d add column if not exists inventory_code varchar(30) unique;
alter table filaments_3d add column if not exists fiscal_invoice_item_id bigint references fiscal_invoice_items(id);
alter table filaments_3d add column if not exists spool_quantity numeric(10,2) not null default 1;
